import { app } from 'electron'
import { readFileSync } from 'fs'
import { join } from 'path'
import type { WhatsNew } from '../shared/ipc'
import { getLastSeenVersion, setLastSeenVersion } from './settings'

/**
 * Release notes are generated by the release workflow and shipped inside the app
 * (build/release-notes.md -> resources/release-notes.md), so this works offline.
 */
function readReleaseNotes(): string {
  const path = app.isPackaged
    ? join(process.resourcesPath, 'release-notes.md')
    : join(app.getAppPath(), 'build/release-notes.md')
  try {
    return readFileSync(path, 'utf8')
  } catch {
    return 'No release notes are available for this build.'
  }
}

/**
 * What to show on start: a welcome the first time the app ever runs, release notes after the
 * version changes, and nothing otherwise. `force` returns the current version's notes on demand.
 */
export function getWhatsNew(force = false): WhatsNew | undefined {
  const version = app.getVersion()
  const lastSeen = getLastSeenVersion()
  if (!force && lastSeen === version) return undefined
  return {
    kind: lastSeen || force ? 'updated' : 'first-run',
    version,
    notes: readReleaseNotes()
  }
}

export function markWhatsNewSeen(): void {
  setLastSeenVersion(app.getVersion())
}
